#[cfg(feature = "validate")]
#[test]
fn rejects_invalid_examples() {
    use trust_tasks_rs::validate::ValidatedPayload;
    let fixtures: &[(&str, &str)] = &[
        (
            "accepts missing — in 0.4 the relying party always states what it will take, so an approver never has to guess.",
            "{\n  \"challenge\": \"Q2hhbExlbmdlVmFsdWVCYXNlNjQ\",\n  \"reason\": \"Confirm transfer\",\n  \"sessionId\": \"ec5d3c89\",\n  \"subject\": \"did:web:alice.example\"\n}",
        ),
        (
            "Empty accepts — an offer of no evidence kind is a step-up nobody can answer.",
            "{\n  \"accepts\": [],\n  \"boundTo\": \"uEiD3n4bE1QbQ8nY2l0cGhYc2FsdGVkZGlnZXN0\",\n  \"challenge\": \"Q2hhbExlbmdlVmFsdWVCYXNlNjQ\",\n  \"reason\": \"Grant the administrator role\",\n  \"subject\": \"did:web:alice.example\"\n}",
        ),
        (
            "Unknown evidence kind in accepts.",
            "{\n  \"accepts\": [\n    \"totp\"\n  ],\n  \"boundTo\": \"uEiD3n4bE1QbQ8nY2l0cGhYc2FsdGVkZGlnZXN0\",\n  \"challenge\": \"Q2hhbExlbmdlVmFsdWVCYXNlNjQ\",\n  \"reason\": \"Grant the administrator role\",\n  \"subject\": \"did:web:alice.example\"\n}",
        ),
        (
            "0.3's acceptableEvidence is replaced by accepts in 0.4 and is now an unknown member.",
            "{\n  \"acceptableEvidence\": [\n    \"webauthn\"\n  ],\n  \"accepts\": [\n    \"webauthn\"\n  ],\n  \"boundTo\": \"uEiD3n4bE1QbQ8nY2l0cGhYc2FsdGVkZGlnZXN0\",\n  \"challenge\": \"Q2hhbExlbmdlVmFsdWVCYXNlNjQ\",\n  \"reason\": \"Grant the administrator role\",\n  \"subject\": \"did:web:alice.example\"\n}",
        ),
        (
            "An approver that is a did:web — a step-up approver is always an Ed25519 did:key, resolvable without a network fetch.",
            "{\n  \"accepts\": [\n    \"approverSigned\"\n  ],\n  \"approvers\": [\n    \"did:web:plugin.example\"\n  ],\n  \"boundTo\": \"uEiD3n4bE1QbQ8nY2l0cGhYc2FsdGVkZGlnZXN0\",\n  \"challenge\": \"Q2hhbExlbmdlVmFsdWVCYXNlNjQ\",\n  \"reason\": \"Grant the administrator role\",\n  \"subject\": \"did:web:alice.example\"\n}",
        ),
        (
            "Empty approvers — when present it names at least one approver the relying party will accept.",
            "{\n  \"accepts\": [\n    \"approverSigned\"\n  ],\n  \"approvers\": [],\n  \"boundTo\": \"uEiD3n4bE1QbQ8nY2l0cGhYc2FsdGVkZGlnZXN0\",\n  \"challenge\": \"Q2hhbExlbmdlVmFsdWVCYXNlNjQ\",\n  \"reason\": \"Grant the administrator role\",\n  \"subject\": \"did:web:alice.example\"\n}",
        ),
        (
            "Challenge too short.",
            "{\n  \"accepts\": [\n    \"didSigned\"\n  ],\n  \"challenge\": \"short\",\n  \"reason\": \"Confirm transfer\",\n  \"sessionId\": \"ec5d3c89\",\n  \"subject\": \"did:web:alice.example\"\n}",
        ),
    ];
    for (i, (note, raw)) in fixtures.iter().enumerate() {
        let value: serde_json::Value = match serde_json::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let serde_ok = serde_json::from_value::<spec::Payload>(value.clone()).is_ok();
        let schema_ok = spec::Payload::validate_value(&value).is_ok();
        assert!(
            !(serde_ok && schema_ok),
            "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
            i + 1,
            note,
            raw
        );
    }
}
